class GoogleMapDetect{constructor(tab,Libraries){this.g=Libraries;this.timer=null;this.tab=tab;this.addr=this.tab.querySelector(".address");this.postc=this.tab.querySelector(".postcode");this.city=this.tab.querySelector(".city");this.country=this.tab.querySelector(".country");this.lat=this.tab.querySelector(".lat");this.lng=this.tab.querySelector(".lng");if(this.addr&&this.city&&this.lat&&this.lng){console.log("GoogleMapDetect : Instance initialisée pour un onglet.");this.init()}else{console.warn("GoogleMapDetect : Des champs requis sont manquants dans cet onglet (addr, city, lat ou lng).")}}async setLatLng(){const parts=[this.addr?.value,this.postc?.value,this.city?.value,this.country?.value].filter((v=>v&&v.trim()!==""));let address=parts.join(", ");if(address.length<10)return;console.log("GoogleMapDetect : Géocodage en cours pour ->",address);const geocoder=new this.g.Geocoder;try{const{results:results}=await geocoder.geocode({address:address});if(results&&results[0]){const location=results[0].geometry.location;this.lat.value=location.lat();this.lng.value=location.lng();[this.lat,this.lng].forEach((el=>{el.style.backgroundColor="#e8f5e9";el.style.transition="background 0.5s";setTimeout((()=>el.style.backgroundColor=""),500)}));console.log("GoogleMapDetect : Succès !",{lat:location.lat(),lng:location.lng()})}}catch(e){console.error("GoogleMapDetect : Erreur ou adresse introuvable.",e)}}updateTimer(callback,timeout=1e3){if(this.timer)clearTimeout(this.timer);this.timer=setTimeout(callback,timeout)}watch(field){if(!field)return;["keyup","focusout","change"].forEach((eventType=>{field.addEventListener(eventType,(()=>{let delay=eventType==="keyup"?1200:100;this.updateTimer((()=>this.setLatLng()),delay)}))}))}init(){[this.addr,this.postc,this.city,this.country].forEach((f=>this.watch(f)))}}async function initMap(){try{if(typeof configMap==="undefined"||!configMap.api_key){throw new Error("La configuration 'configMap' est manquante ou incomplète.")}const{Geocoder:Geocoder}=await google.maps.importLibrary("geocoding");let tabs=document.querySelectorAll(".tab-pane");if(tabs.length===0){console.info("GoogleMapDetect : Aucun .tab-pane trouvé sur cette page.");return}tabs.forEach((tab=>{new GoogleMapDetect(tab,{Geocoder:Geocoder})}))}catch(e){console.error("GoogleMapDetect : Échec de l'initialisation.",e)}}(g=>{var h,a,k,p="The Google Maps JavaScript API",c="google",l="importLibrary",q="__ib__",m=document,b=window;b=b[c]||(b[c]={});var d=b.maps||(b.maps={}),r=new Set,e=new URLSearchParams,u=()=>h||(h=new Promise((async(f,n)=>{await(a=m.createElement("script"));e.set("libraries",[...r]+"");for(k in g)e.set(k.replace(/[A-Z]/g,(t=>"_"+t[0].toLowerCase())),g[k]);e.set("callback",c+".maps."+q);a.src=`https://maps.${c}apis.com/maps/api/js?`+e;d[q]=f;a.onerror=()=>h=n(Error(p+" could not load."));a.nonce=m.querySelector("script[nonce]")?.nonce||"";m.head.append(a)})));d[l]?console.warn(p+" only loads once. Ignoring:",g):d[l]=(f,...n)=>r.add(f)&&u().then((()=>d[l](f,...n)))})({key:configMap.api_key,v:"weekly",lang:configMap.lang});initMap();